// Package art is the backend's registry of the pixel-art sprites in frontend/public/art/monsters.
//
// The registry is generated by scripts/pixel-art/build.mjs (sprites_gen.go). Content that needs art, such as
// monster definitions, refers to it through the exported SpriteID and ThemeID variables. Their fields are
// unexported, so no other package can invent or misspell an id: a reference to art that was never built does
// not compile. The zero SpriteID means "no art"; Known reports false for it so catalog validation can reject it.
package art

// ThemeID identifies an art theme, for example the Sunken Kingdom. Use the Theme* variables.
type ThemeID struct{ id string }

// String returns the stable theme folder name used under /art/monsters/.
func (t ThemeID) String() string { return t.id }

// SpriteID identifies one creature's sprite sheet. Use the generated per-creature variables.
type SpriteID struct{ id string }

// String returns "<theme>/<creature>", which is also the sheet path stem and the id sent to clients.
func (s SpriteID) String() string { return s.id }

// Theme describes an art theme.
type Theme struct {
	ID      ThemeID
	Name    string
	Tagline string
}

// Sprite describes one creature's sprite sheet.
type Sprite struct {
	ID         SpriteID
	Theme      ThemeID
	CreatureID string
	Name       string
	Boss       bool
	// Sheet is the PNG path relative to frontend/public/art/monsters.
	Sheet string
	// FrameSize is the square frame edge in pixels: 64 for monsters, 128 for bosses.
	FrameSize int
}

// Sprites returns every sprite the art pipeline produced.
func Sprites() []Sprite { return append([]Sprite(nil), sprites...) }

// Themes returns every art theme.
func Themes() []Theme { return append([]Theme(nil), themes...) }

// Lookup returns the sprite for id, or false if id is the zero value or not a generated sprite.
func Lookup(id SpriteID) (Sprite, bool) {
	for _, sprite := range sprites {
		if sprite.ID == id {
			return sprite, true
		}
	}
	return Sprite{}, false
}

// Known reports whether id is a generated sprite.
func Known(id SpriteID) bool {
	_, ok := Lookup(id)
	return ok
}

// KnownTheme reports whether id is a generated art theme.
func KnownTheme(id ThemeID) bool {
	for _, theme := range themes {
		if theme.ID == id {
			return true
		}
	}
	return false
}

// ThemeOf returns the art theme a sprite belongs to.
func ThemeOf(id SpriteID) (ThemeID, bool) {
	sprite, ok := Lookup(id)
	return sprite.Theme, ok
}

// ParseSprite resolves a "<theme>/<creature>" string, such as one read from a persisted run.
func ParseSprite(s string) (SpriteID, bool) {
	for _, sprite := range sprites {
		if sprite.ID.id == s {
			return sprite.ID, true
		}
	}
	return SpriteID{}, false
}
